# gpm-cli offline installer (Windows PowerShell)
# No network or git required.
#
# Usage:
#   .\gpm-cli-install.ps1
#   .\gpm-cli-install.ps1 -SkillOnly     # install Skill only
#   .\gpm-cli-install.ps1 -CliOnly       # install CLI only

param(
    [switch]$SkillOnly,
    [switch]$CliOnly
)

$ErrorActionPreference = "Stop"

function Write-Info($msg)  { Write-Host "  $msg" -ForegroundColor Cyan }
function Write-Ok($msg)    { Write-Host "  [*] $msg" -ForegroundColor Green }
function Write-Warn($msg)  { Write-Host "  [!] $msg" -ForegroundColor Yellow }
function Write-Fail($msg)  { Write-Host "  [X] $msg" -ForegroundColor Red }

Write-Host ""
Write-Host "=== gpm-cli 安装 ===" -ForegroundColor White
Write-Host ""

# ── Environment checks ──────────────────────────────────────────────────
$problems = 0

Write-Host "  环境检查" -ForegroundColor White
Write-Host ""

# Python (try each command, skip MS Store stubs that fail at runtime)
$pyCmd = $null
$pyVer = $null
foreach ($cmd in @("python", "python3", "py")) {
    try {
        $null = Get-Command $cmd -ErrorAction Stop
        $verRaw = & $cmd -c "import sys; print(sys.version_info.major, sys.version_info.minor)" 2>&1
        if ($LASTEXITCODE -eq 0 -and $verRaw) {
            $pyCmd = $cmd
            $pyVer = $verRaw
            break
        }
    } catch {}
}

if (-not $pyCmd) {
    Write-Fail "Python - 未安装或不可用"

    Write-Host "      请安装 Python 3.6+: https://www.python.org/downloads/"
    $problems++
} else {
    $major = [int]$pyVer.Split()[0]
    $minor = [int]$pyVer.Split()[1]
    $ver = "$major.$minor"

    if ($major -lt 3 -or ($major -eq 3 -and $minor -lt 6)) {

        Write-Fail "Python $ver - 版本过低，需要 3.6+"
        Write-Host "      请升级 Python: https://www.python.org/downloads/"
        $problems++
    } else {
        Write-Ok "Python $ver"
    }
}

# pip
$pipCmd = $null
foreach ($cmd in @("pip", "pip3")) {
    try {
        $null = Get-Command $cmd -ErrorAction Stop
        $pipCmd = $cmd
        break
    } catch {}
}
if (-not $pipCmd) {
    Write-Fail "pip - 未安装"
    Write-Host "      通常随 Python 一起安装，或运行: python -m ensurepip"
    $problems++
} else {
    Write-Ok "pip 已安装"
}

Write-Host ""
if ($problems -gt 0) {
    Write-Host "  发现 $problems 个问题，请修复后重新运行安装脚本。" -ForegroundColor Red -BackgroundColor Black
    Write-Host ""
    exit 1
}
Write-Host "  环境检查通过" -ForegroundColor Green
Write-Host ""

