'@
    $tempDir = Join-Path $env:TEMP "gpm-cli-install-$(Get-Random)"
    New-Item -ItemType Directory -Path $tempDir -Force | Out-Null

    $wheelBytes = [System.Convert]::FromBase64String(($wheelB64 -replace '\s',''))

    [System.IO.File]::WriteAllBytes((Join-Path $tempDir "gpm_cli-0.1.5-py3-none-any.whl"), $wheelBytes)
    Write-Ok "CLI 包解码完成"

    Write-Info "安装 CLI..."

    $pipLog = Join-Path $tempDir "pip.log"
    $prevEAP = $ErrorActionPreference
    $ErrorActionPreference = "Continue"
    $pipOutput = & $pipCmd install "$tempDir\gpm_cli-0.1.5-py3-none-any.whl" --disable-pip-version-check --force-reinstall 2>&1
    $pipExit = $LASTEXITCODE
    $ErrorActionPreference = $prevEAP
    $pipOutput | Out-File $pipLog -Encoding UTF8
    if ($pipExit -ne 0) {
        Write-Host ""
        Write-Fail "CLI 安装失败"
        Write-Host ""
        if (Test-Path $pipLog) {
            Write-Host "  pip 输出:" -ForegroundColor Yellow
            Get-Content $pipLog | ForEach-Object { Write-Host "    $_" }
            Write-Host ""
        }
        Write-Host "  常见原因:" -ForegroundColor Yellow
        Write-Host "    1. Python 版本过低 - 需要 3.6+"
        Write-Host "    2. pip 权限不足 - 尝试: pip install --user ..."
        Write-Host "    3. 依赖冲突 - 尝试: pip install --force-reinstall ..."
        Write-Host ""
        exit 1
    }
    Write-Ok "gpm-cli 已安装"

    # Ensure Python Scripts directory is on PATH
    $scriptsDir = $null
    try {
        $scriptsDir = (& $pyCmd -c "import sysconfig; print(sysconfig.get_path('scripts'))" 2>$null).Trim()
    } catch {}

    if ($scriptsDir -and (Test-Path $scriptsDir)) {
        $normScripts = $scriptsDir.TrimEnd('\')
        $pathParts = $env:PATH -split ';' | ForEach-Object { $_.TrimEnd('\') }
        $onPath = $pathParts | Where-Object { $_ -ieq $normScripts }

        if (-not $onPath) {
            # Add to current session
            $env:PATH = "$env:PATH;$scriptsDir"

            # Add to user PATH permanently
            $userPath = [Environment]::GetEnvironmentVariable("PATH", "User")
            $userPathParts = $userPath -split ';' | ForEach-Object { $_.TrimEnd('\') }
            $inUserPath = $userPathParts | Where-Object { $_ -ieq $normScripts }
            if (-not $inUserPath) {
                [Environment]::SetEnvironmentVariable("PATH", "$userPath;$scriptsDir", "User")
                Write-Ok "已将 Scripts 目录添加到用户 PATH: $scriptsDir"
            }
            Write-Warn "请重新打开终端窗口，PATH 更改才会完全生效"
        }
    }

    # Verify gpm-cli is accessible
    try {
        $gpmPath = Get-Command "gpm-cli" -ErrorAction Stop
        Write-Ok "gpm-cli 命令可用: $($gpmPath.Source)"
    } catch {
        if ($scriptsDir) {
            Write-Warn "gpm-cli 未在 PATH 中找到"
            Write-Host "      请将以下目录添加到 PATH: $scriptsDir" -ForegroundColor Yellow
            Write-Host "      或重新打开终端窗口后重试" -ForegroundColor Yellow
        }
    }

    Remove-Item -Recurse -Force $tempDir -ErrorAction SilentlyContinue
}

