gOaxguOAggo=
'@
    $tempDir = Join-Path $env:TEMP "gpm-cli-install-$(Get-Random)"
    New-Item -ItemType Directory -Path $tempDir -Force | Out-Null

    $skillBytes = [System.Convert]::FromBase64String(($skillB64 -replace '\s',''))
    [System.IO.File]::WriteAllBytes((Join-Path $tempDir "SKILL.md"), $skillBytes)
    Write-Ok "Skill 文件解码完成"

    $userHome = $env:USERPROFILE
    $installed = 0

    if (Test-Path "$userHome\.claude") {
        New-Item -ItemType Directory -Path "$userHome\.claude\skills\gpm-cli" -Force | Out-Null
        Copy-Item (Join-Path $tempDir "SKILL.md") "$userHome\.claude\skills\gpm-cli\SKILL.md" -Force
        Write-Ok "Claude Code -> ~/.claude/skills/gpm-cli/SKILL.md"
        $installed++
    }

    if (Test-Path "$userHome\.codex") {
        New-Item -ItemType Directory -Path "$userHome\.codex\skills" -Force | Out-Null
        Copy-Item (Join-Path $tempDir "SKILL.md") "$userHome\.codex\skills\gpm-cli.md" -Force
        Write-Ok "Codex -> ~/.codex/skills/gpm-cli.md"
        $installed++
    }

    if (Test-Path "$userHome\.opencode") {
        New-Item -ItemType Directory -Path "$userHome\.opencode\skills" -Force | Out-Null
        Copy-Item (Join-Path $tempDir "SKILL.md") "$userHome\.opencode\skills\gpm-cli.md" -Force
        Write-Ok "OpenCode -> ~/.opencode/skills/gpm-cli.md"
        $installed++
    }

    if (Test-Path "$userHome\.cursor") {
        New-Item -ItemType Directory -Path "$userHome\.cursor\skills\gpm-cli" -Force | Out-Null
        Copy-Item (Join-Path $tempDir "SKILL.md") "$userHome\.cursor\skills\gpm-cli\SKILL.md" -Force
        Write-Ok "Cursor -> ~/.cursor/skills/gpm-cli/SKILL.md"
        $installed++
    }

    if ($installed -eq 0) {
        Write-Warn "未检测到已安装的 AI Agent"
        Write-Host ""
        Write-Host "  支持的 Agent:"

        Write-Host "    Claude Code"
        Write-Host "    Codex"
        Write-Host "    OpenCode"
        Write-Host "    Cursor"
    }

    Remove-Item -Recurse -Force $tempDir -ErrorAction SilentlyContinue
}

# ── Main ─────────────────────────────────────────────────────────────────
if ($SkillOnly) {
    Install-Skill
} elseif ($CliOnly) {
    Install-Cli
} else {
    Install-Cli
    Write-Host ""
    Install-Skill
}

Write-Host ""
Write-Host "=== 安装完成 ===" -ForegroundColor Green
Write-Host ""
Write-Host "  重启 AI Agent 后使用 /gpm-cli 即可开始。"
Write-Host "  首次使用请运行: gpm-cli login"
Write-Host ""
